"use strict";(self.webpackChunk=self.webpackChunk||[]).push([["1012"],{8941:function(s,a,n){n.r(a),n.d(a,{default:function(){return p}});var t=n(1147);let l=["innerHTML"],p={setup:()=>({html:""}),render:()=>((0,t.wg)(),(0,t.iD)("div",{class:"mi-doc-markdown-body",innerHTML:'<h1>选择器弹层页</h1>\n<div class="mi-doc-card"><h3 id="jie-shao" tabindex="-1">介绍</h3>\n<p>选择器弹层页适合地区、类目、时间范围和组合条件选择等移动业务页面。</p>\n<p>该场景使用 <code>Cell</code>、<code>Popup</code>、<code>Tabs</code>、<code>Picker</code>、<code>Tag</code> 和 <code>Button</code> 组合出一个底部选择面板，包含已选结果、弹层容器、维度切换、选择器主体和确认动作。</p>\n</div><div class="mi-doc-card"><h3 id="tui-jian-zu-jian" tabindex="-1">推荐组件</h3>\n<table>\n<thead>\n<tr>\n<th>组件</th>\n<th>作用</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Cell</td>\n<td>展示已选值和触发入口</td>\n</tr>\n<tr>\n<td>Popup</td>\n<td>底部弹层容器</td>\n</tr>\n<tr>\n<td>Tabs</td>\n<td>切换选择维度</td>\n</tr>\n<tr>\n<td>Picker</td>\n<td>单列或多列选择</td>\n</tr>\n<tr>\n<td>Tag</td>\n<td>标记推荐项或当前状态</td>\n</tr>\n<tr>\n<td>Button</td>\n<td>确认选择</td>\n</tr>\n</tbody>\n</table>\n</div><div class="mi-doc-card"><h3 id="shi-li-dai-ma" tabindex="-1">示例代码</h3>\n<pre><code class="language-html"><span class="hljs-tag">&lt;<span class="hljs-name">mi-nav-bar</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;选择配送区域&quot;</span> <span class="hljs-attr">left-arrow</span> <span class="hljs-attr">left-text</span>=<span class="hljs-string">&quot;返回&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-cell-group</span> <span class="hljs-attr">inset</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;当前选择&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-cell</span>\n        <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;配送区域&quot;</span>\n        <span class="hljs-attr">:value</span>=<span class="hljs-string">&quot;selectedArea&quot;</span>\n        <span class="hljs-attr">is-link</span>\n        @<span class="hljs-attr">click</span>=<span class="hljs-string">&quot;showPicker = true&quot;</span>\n    /&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-cell</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;服务状态&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">template</span> #<span class="hljs-attr">value</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">mi-tag</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;success&quot;</span>&gt;</span>可配送<span class="hljs-tag">&lt;/<span class="hljs-name">mi-tag</span>&gt;</span>\n        <span class="hljs-tag">&lt;/<span class="hljs-name">template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">mi-cell</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-cell-group</span>&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-popup</span> <span class="hljs-attr">v-model:show</span>=<span class="hljs-string">&quot;showPicker&quot;</span> <span class="hljs-attr">round</span> <span class="hljs-attr">closeable</span> <span class="hljs-attr">position</span>=<span class="hljs-string">&quot;bottom&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-tabs</span> <span class="hljs-attr">v-model:active</span>=<span class="hljs-string">&quot;activeTab&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">mi-tab</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;常用区域&quot;</span> /&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">mi-tab</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;全部区域&quot;</span> /&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">mi-tabs</span>&gt;</span>\n\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-picker</span>\n        <span class="hljs-attr">v-model</span>=<span class="hljs-string">&quot;selectedValues&quot;</span>\n        <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;行政区&quot;</span>\n        <span class="hljs-attr">:columns</span>=<span class="hljs-string">&quot;areaColumns&quot;</span>\n        @<span class="hljs-attr">confirm</span>=<span class="hljs-string">&quot;onConfirm&quot;</span>\n    /&gt;</span>\n\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-button</span> <span class="hljs-attr">round</span> <span class="hljs-attr">block</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;primary&quot;</span> @<span class="hljs-attr">click</span>=<span class="hljs-string">&quot;showPicker = false&quot;</span>&gt;</span>\n        暂不修改\n    <span class="hljs-tag">&lt;/<span class="hljs-name">mi-button</span>&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-popup</span>&gt;</span>\n</code></pre>\n</div><div class="mi-doc-card"><h3 id="gua-yong-chang-jing" tabindex="-1">适用场景</h3>\n<ul>\n<li>配送区域、服务城市、门店选择</li>\n<li>类目、标签、时间范围等组合条件</li>\n<li>需要在移动端保持页面上下文的选择流程</li>\n</ul>\n</div><div class="mi-doc-card"><h3 id="shi-yong-jian-yi" tabindex="-1">使用建议</h3>\n<ul>\n<li>弹层标题和触发入口文案保持一致，减少用户理解成本。</li>\n<li>选择项较多时优先使用底部弹层，避免跳转到独立页面。</li>\n<li>已选结果回填到 <code>Cell</code>，让用户关闭弹层后仍能确认当前选择。</li>\n</ul>\n</div>'},null,8,l))}}}]);